[[nodiscard]] inline constexpr std::optional<std::string_view> qzss_dcr_jma_local_government_lookup(uint32_t id) noexcept {
    uint16_t lo = 0, hi = 1792;
    while (lo < hi) {
        uint16_t mid = static_cast<uint16_t>(lo + (hi - lo) / 2);
        if (QZSS_DCR_JMA_LOCAL_GOVERNMENT_TABLE[mid].id == id) {
            const char* s = QZSS_DCR_JMA_LOCAL_GOVERNMENT_TABLE[mid].label;
            return s ? std::optional<std::string_view>(std::string_view{s}) : std::nullopt;
        }
        if (QZSS_DCR_JMA_LOCAL_GOVERNMENT_TABLE[mid].id < id) lo = mid + 1;
        else hi = mid;
    }
    return std::nullopt;
}
